<?php $concept=!empty($item['concept']);?><div class="container"><header class="page-heading"><span class="eyebrow"><?=e($concept?'CONCEPT PROJECT · '.$item['industry']:$item['industry'].' / CASE STUDY')?></span><h1><?=e($item['title'])?></h1><p><?=e($item['description'])?></p></header><div class="case-meta"><div><span>Project type</span><?=e($concept?'Concept demonstration':'Completed project')?></div><div><span>Industry</span><?=e($item['industry'])?></div><div><span>Architecture</span><?=e($item['architecture'])?></div><?php if(!empty($item['technologies'])):?><div><span><?=$concept?'Proposed stack':'Technologies'?></span><?=e(implode(' · ',$item['technologies']))?></div><?php endif;?></div><div class="case-hero"><?php project_visual($item);?></div><div class="article-layout"><article class="prose"><h2 id="overview"><?=$concept?'Concept overview':'Project overview'?></h2><p><?=e($item['description'])?> <?=$concept?'This self-directed concept demonstrates how I would approach the product, workflows and technical structure; it is not presented as commissioned client work.':'This case study outlines the application’s purpose, the functionality developed and the operational context behind the work.'?></p><h2 id="problem"><?=$concept?'The business challenge':'The client problem'?></h2><p><?=e($item['problem'])?></p><h2 id="solution"><?=$concept?'The proposed solution':'The solution'?></h2><p><?=e($item['solution'])?></p><h2 id="features"><?=$concept?'Capabilities demonstrated':'Features developed'?></h2><?php $featureGroups=[];foreach($item['features'] as $f){$parts=explode(': ',$f,2);$group=count($parts)===2&&in_array($parts[0],['Website','Admin panel'])?$parts[0]:'';$featureGroups[$group][]=$group?$parts[1]:$f;}foreach($featureGroups as $group=>$features):?><?php if($group):?><h3><?=e($group==='Website'?'Public website features':'Admin panel features')?></h3><?php endif;?><ul class="feature-list"><?php foreach($features as $f):?><li><?=e($f)?></li><?php endforeach;?></ul><?php endforeach;?><?php if(!empty($item['technologies'])):?><h2 id="technology"><?=$concept?'Proposed technology stack':'Technologies used'?></h2><div class="tags"><?php foreach($item['technologies'] as $t):?><span><?=e($t)?></span><?php endforeach;?></div><p><a href="/technologies">Explore my technology stack and development approach.</a></p><?php endif;?><h2 id="contribution"><?=$concept?'What this concept demonstrates':'My contribution'?></h2><p><?=e($item['contribution'])?></p><h2 id="screenshots">A closer look</h2><?php if($item['screenshots']):foreach($item['screenshots'] as $s):?><figure class="screenshot"><a href="<?=e($s['src'])?>" target="_blank" rel="noopener"><img src="<?=e($s['src'])?>" width="1200" height="600" loading="lazy" decoding="async" alt="<?=e($s['alt'])?>"></a><figcaption><?=e($s['alt'])?> · Open full image</figcaption></figure><?php endforeach;else:?><p class="asset-note"><?=$concept?'The visual above is a concept system overview rather than a production application screenshot.':'The visual above is a system overview, not an application screenshot. Approved project screenshots will be added when available.'?></p><?php endif;?><h2 id="impact"><?=$concept?'Potential business value':'Business impact'?></h2><p><?=e($item['impact'])?></p><h2>Related services</h2><div class="related-links"><?php foreach($item['related_services'] as $slug):$s=record('services',$slug);if($s):?><a href="/services/<?=e($slug)?>"><?=e($s['title'])?> ↗</a><?php endif;endforeach;?></div></article><aside><div class="sidebar-box"><h2>Inside this <?=$concept?'concept':'project'?></h2><ul><?php foreach(['overview'=>$concept?'Concept overview':'Project overview','problem'=>$concept?'Business challenge':'Client problem','solution'=>$concept?'Proposed solution':'The solution','features'=>$concept?'Capabilities':'Features developed','technology'=>$concept?'Proposed stack':'Technologies','contribution'=>$concept?'What it demonstrates':'My contribution','screenshots'=>'A closer look','impact'=>$concept?'Potential value':'Business impact'] as $id=>$label):if($id==='technology'&&empty($item['technologies']))continue;?><li><a href="#<?=$id?>"><?=$label?></a></li><?php endforeach;?></ul><h3>Need a similar system?</h3><p>Let’s discuss your workflows and what the right solution could look like.</p><a class="button" href="/contact">Discuss your project <?=icon('arrow')?></a></div></aside></div></div><?php cta('Need a similar system?<br>Let’s build your version.');?>
